"""Recover bounded station guidance parameters; emit no executable payload."""
import copy
from .declaration_layouts import recognize
from .station_exterior import declaration_bytes
from .scenery_population import import_symbol

def extract_station_autopilot(mach, arrival, flight):
    if mach.architecture!='x86_64' or flight.get('scope')!='first_mining_flight_construction':return {}
    try:
        origin=arrival['provenance']['actor']
        if origin['bytes']!=315:return {}
        layouts=[{k:[v[2],v[0],v[1],v[3]] for k,v in rows.items()} for rows in [LAYOUTS,MAC_ALTERNATE]]
        proof=recognize(mach,origin['offset'],layouts,reader=declaration_bytes)
        if not proof:return {}
        imports=MAC_IMPORTS if proof['matrix_xyz']['offset']==origin['offset']+MAC_ALTERNATE['matrix_xyz'][0] else IMPORTS
        anchor=mach.text['address']+origin['offset']-mach.slice_offset-mach.text['offset']
        if any(import_symbol(mach,anchor+delta)!=symbol.encode() for symbol,delta in imports.items()):return {}
        values=VALUES
        result=copy.deepcopy(values);result['provenance']=proof
        return result
    except (KeyError,TypeError,ValueError,IndexError,OverflowError):return {}

